-- ============ Part 2: rules, security (hand-written) ============

ALTER TABLE meetings
  ADD CONSTRAINT meetings_type_check CHECK (type IN ('INSTANT', 'ROOM', 'SCHEDULED')),
  ADD CONSTRAINT meetings_status_check CHECK (status IN ('SCHEDULED', 'LIVE', 'ENDED', 'CANCELLED')),
  ADD CONSTRAINT meetings_schedule_check CHECK (type <> 'SCHEDULED' OR (scheduled_start IS NOT NULL AND scheduled_end > scheduled_start)),
  ADD CONSTRAINT meetings_room_check CHECK (type <> 'ROOM' OR room_id IS NOT NULL);
-- One live room meeting per office room.
CREATE UNIQUE INDEX meetings_one_live_room ON meetings (room_id) WHERE type = 'ROOM' AND status = 'LIVE';
ALTER TABLE meeting_attendees
  ADD CONSTRAINT meeting_attendees_role_check CHECK (role IN ('HOST', 'COHOST', 'ATTENDEE')),
  ADD CONSTRAINT meeting_attendees_response_check CHECK (response IN ('NEEDS_ACTION', 'ACCEPTED', 'DECLINED'));
ALTER TABLE meeting_lobby
  ADD CONSTRAINT meeting_lobby_state_check CHECK (state IN ('WAITING', 'ADMITTED', 'DENIED'));
ALTER TABLE meeting_participants
  ADD CONSTRAINT meeting_participants_times_check CHECK (left_at IS NULL OR left_at >= joined_at),
  ADD CONSTRAINT meeting_participants_duration_check CHECK (duration_seconds >= 0);

DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['meetings', 'meeting_attendees', 'meeting_participants', 'meeting_lobby', 'meeting_action_items'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR ALL
         USING (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)
         WITH CHECK (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)',
      t || '_org_policy', t);
  END LOOP;
END
$$;
GRANT SELECT, INSERT, UPDATE ON meetings, meeting_participants TO hrvo_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON meeting_attendees, meeting_lobby, meeting_action_items TO hrvo_app;
-- Join/leave records are attendance evidence: never deleted by the application.
REVOKE DELETE, TRUNCATE ON meetings, meeting_participants FROM hrvo_app;

CREATE FUNCTION fn_meeting_same_org() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_TABLE_NAME = 'meetings' THEN
    IF NOT EXISTS (SELECT 1 FROM users u WHERE u.id = NEW.host_id AND u.org_id = NEW.org_id) THEN
      RAISE EXCEPTION 'meeting host belongs to another organisation';
    END IF;
    IF NEW.room_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM rooms r WHERE r.id = NEW.room_id AND r.org_id = NEW.org_id) THEN
        RAISE EXCEPTION 'meeting room belongs to another organisation';
      END IF;
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM meetings m WHERE m.id = NEW.meeting_id AND m.org_id = NEW.org_id) THEN
      RAISE EXCEPTION 'meeting belongs to another organisation';
    END IF;
    IF TG_TABLE_NAME IN ('meeting_attendees', 'meeting_participants', 'meeting_lobby') THEN
      IF NOT EXISTS (SELECT 1 FROM users u WHERE u.id = NEW.user_id AND u.org_id = NEW.org_id) THEN
        RAISE EXCEPTION 'meeting participant belongs to another organisation';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER meetings_same_org BEFORE INSERT OR UPDATE ON meetings FOR EACH ROW EXECUTE FUNCTION fn_meeting_same_org();
CREATE TRIGGER meeting_attendees_same_org BEFORE INSERT OR UPDATE ON meeting_attendees FOR EACH ROW EXECUTE FUNCTION fn_meeting_same_org();
CREATE TRIGGER meeting_participants_same_org BEFORE INSERT OR UPDATE ON meeting_participants FOR EACH ROW EXECUTE FUNCTION fn_meeting_same_org();
CREATE TRIGGER meeting_lobby_same_org BEFORE INSERT OR UPDATE ON meeting_lobby FOR EACH ROW EXECUTE FUNCTION fn_meeting_same_org();
CREATE TRIGGER meeting_action_items_same_org BEFORE INSERT OR UPDATE ON meeting_action_items FOR EACH ROW EXECUTE FUNCTION fn_meeting_same_org();

-- LiveKit webhooks name a room, not a tenant; this maps a room name to its organisation.
CREATE FUNCTION fn_meeting_by_livekit_room(p_room VARCHAR)
RETURNS TABLE (id UUID, org_id UUID)
SECURITY DEFINER
SET search_path = public
LANGUAGE sql STABLE AS $$
  SELECT m.id, m.org_id FROM meetings m WHERE m.livekit_room_name = p_room;
$$;
REVOKE ALL ON FUNCTION fn_meeting_by_livekit_room(VARCHAR) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_meeting_by_livekit_room(VARCHAR) TO hrvo_app;
